import {
  createContext,
  useContext,
  useEffect,
  useState,
  ReactNode,
} from "react";
import {
  adminLogin,
  adminRegister,
  logout as cloudbaseLogout,
  getCurrentUser,
  ensureAnonymousLogin,
} from "@/lib/cloudbase";

export interface AuthUser {
  uid: string;
  email: string | null;
  isAdmin: boolean;
}

interface AuthContextType {
  user: AuthUser | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// CloudBase 的 User 对象中只有 email 才算管理员（通过邮箱密码登录的用户）
// 匿名登录的用户 isAdmin = false
function toAuthUser(rawUser: { uid: string; email?: string | null } | null): AuthUser | null {
  if (!rawUser) return null;
  return {
    uid: rawUser.uid,
    email: rawUser.email || null,
    isAdmin: !!rawUser.email, // 只有邮箱密码用户才是管理员
  };
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    // 首次加载：先匿名登录，再检查是否已登录
    ensureAnonymousLogin()
      .then(() => getCurrentUser())
      .then((currentUser) => {
        if (!cancelled) {
          setUser(toAuthUser(currentUser as { uid: string; email?: string | null } | null));
          setLoading(false);
        }
      })
      .catch(() => {
        if (!cancelled) {
          setUser(null);
          setLoading(false);
        }
      });
    return () => { cancelled = true; };
  }, []);

  const login = async (email: string, password: string) => {
    const result = await adminLogin(email, password);
    const user = (result as { user?: { uid: string; email?: string | null } }).user;
    setUser(toAuthUser(user || null));
  };

  const register = async (email: string, password: string) => {
    const result = await adminRegister(email, password);
    const user = (result as { user?: { uid: string; email?: string | null } }).user;
    setUser(toAuthUser(user || null));
  };

  const logout = async () => {
    await cloudbaseLogout();
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, register, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}
