import { getDb, ensureAnonymousLogin } from "@/lib/cloudbase";

export interface TimelineItem {
  year: string;
  title: string;
  description: string;
}

export interface Profile {
  name: string;
  avatar: string;
  background: string;
  bio: string;
  role: string;
  location: string;
  aboutContent: string;
  timeline: TimelineItem[];
  social: {
    github?: string;
    twitter?: string;
    email?: string;
    rss?: string;
  };
  updatedAt?: number;
}

const PROFILE_DOC = "site";
const COLLECTION = "profile";

function toMillis(value: unknown): number | undefined {
  if (!value) return undefined;
  if (value instanceof Date) return value.getTime();
  if (
    value &&
    typeof value === "object" &&
    "toMillis" in value &&
    typeof (value as { toMillis: () => number }).toMillis === "function"
  ) {
    return (value as { toMillis: () => number }).toMillis();
  }
  return undefined;
}

export async function getProfile(): Promise<Profile | null> {
  await ensureAnonymousLogin();
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const res = await collection.limit(50).get();
  const data = (res.data as Array<Record<string, unknown>>).find(
    (item) => item._id === PROFILE_DOC || (item as { _id?: string })._id === PROFILE_DOC
  );
  if (!data) return null;
  return {
    name: (data.name as string) ?? "",
    avatar: (data.avatar as string) ?? "",
    background: (data.background as string) ?? "",
    bio: (data.bio as string) ?? "",
    role: (data.role as string) ?? "",
    location: (data.location as string) ?? "",
    aboutContent: (data.aboutContent as string) ?? "",
    timeline: Array.isArray(data.timeline) ? (data.timeline as TimelineItem[]) : [],
    social: (data.social as Profile["social"]) ?? {},
    updatedAt: toMillis(data.updatedAt),
  };
}

export async function updateProfile(profile: Partial<Profile>): Promise<void> {
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const doc = collection.doc(PROFILE_DOC);

  // 先检查文档是否存在
  const existing = await collection
    .where({ _id: PROFILE_DOC })
    .limit(1)
    .get();

  const updateData: Record<string, unknown> = { ...profile, updatedAt: new Date() };
  delete updateData._id;

  if (!existing.data || existing.data.length === 0) {
    // 不存在则创建
    await collection.add({ _id: PROFILE_DOC, ...updateData } as unknown as Record<string, unknown>);
  } else {
    await doc.update(updateData);
  }
}
