import { getDb, ensureAnonymousLogin } from "@/lib/cloudbase";

export interface Post {
  _id?: string;
  id?: string;
  slug: string;
  title: string;
  date: string;
  summary: string;
  tags: string[];
  featured?: boolean;
  readingTime: number;
  content: string;
  createdAt?: number;
  updatedAt?: number;
}

const COLLECTION = "posts";

function formatDate(date: Date): string {
  return date.toISOString().split("T")[0];
}

function normalizeDate(value: unknown): string {
  if (typeof value === "string") return value;
  if (value instanceof Date) return formatDate(value);
  if (
    value &&
    typeof value === "object" &&
    "toDate" in value &&
    typeof (value as { toDate: () => Date }).toDate === "function"
  ) {
    return formatDate((value as { toDate: () => Date }).toDate());
  }
  return "";
}

function toMillis(value: unknown): number | undefined {
  if (!value) return undefined;
  if (value instanceof Date) return value.getTime();
  if (
    value &&
    typeof value === "object" &&
    "toMillis" in value &&
    typeof (value as { toMillis: () => number }).toMillis === "function"
  ) {
    return (value as { toMillis: () => number }).toMillis();
  }
  return undefined;
}

export async function getPosts(): Promise<Post[]> {
  await ensureAnonymousLogin();
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const res = await collection
    .orderBy("date", "desc")
    .limit(100)
    .get();
  return (res.data as Post[]).map((item) => ({
    id: item._id,
    slug: item.slug ?? "",
    title: item.title ?? "",
    date: normalizeDate(item.date),
    summary: item.summary ?? "",
    tags: Array.isArray(item.tags) ? item.tags : [],
    featured: item.featured === true,
    readingTime: item.readingTime || Math.ceil((item.content?.length || 0) / 500),
    content: item.content ?? "",
    createdAt: toMillis(item.createdAt),
    updatedAt: toMillis(item.updatedAt),
  }));
}

export async function getPostBySlug(slug: string): Promise<Post | null> {
  await ensureAnonymousLogin();
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const res = await collection
    .orderBy("date", "desc")
    .limit(200)
    .get();
  const found = (res.data as Post[]).find((item) => item.slug === slug);
  if (!found) return null;
  return {
    id: found._id,
    slug: found.slug ?? "",
    title: found.title ?? "",
    date: normalizeDate(found.date),
    summary: found.summary ?? "",
    tags: Array.isArray(found.tags) ? found.tags : [],
    featured: found.featured === true,
    readingTime: found.readingTime || Math.ceil((found.content?.length || 0) / 500),
    content: found.content ?? "",
    createdAt: toMillis(found.createdAt),
    updatedAt: toMillis(found.updatedAt),
  };
}

export async function createPost(post: Omit<Post, "id">): Promise<string> {
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const now = new Date();
  const res = await collection.add({
    ...post,
    date: post.date || formatDate(now),
    tags: post.tags || [],
    featured: post.featured === true,
    readingTime: post.readingTime || Math.ceil((post.content?.length || 0) / 500),
    createdAt: now,
    updatedAt: now,
  } as unknown as Record<string, unknown>);
  return (res as { id: string }).id;
}

export async function updatePost(id: string, post: Partial<Post>): Promise<void> {
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const doc = collection.doc(id);
  const updateData: Record<string, unknown> = { ...post, updatedAt: new Date() };
  delete updateData.id;
  delete updateData._id;
  await doc.update(updateData);
}

export async function deletePost(id: string): Promise<void> {
  const db = getDb();
  const collection = db.collection(COLLECTION);
  await collection.doc(id).remove();
}

export function formatDisplayDate(date: string): string {
  const d = new Date(date);
  return `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;
}
