import { getDb, ensureAnonymousLogin } from "@/lib/cloudbase";

export interface DevLog {
  id?: string;
  title: string;
  date: string;
  content: string;
}

export interface Game {
  _id?: string;
  id?: string;
  slug: string;
  title: string;
  genre: string;
  summary: string;
  description: string;
  cover: string;
  demoUrl?: string;
  tags: string[];
  devLogs: DevLog[];
  featured?: boolean;
  createdAt?: number;
  updatedAt?: number;
}

const COLLECTION = "games";

function formatDate(date: Date): string {
  return date.toISOString().split("T")[0];
}

function normalizeDate(value: unknown): string {
  if (typeof value === "string") return value;
  if (value instanceof Date) return formatDate(value);
  if (
    value &&
    typeof value === "object" &&
    "toDate" in value &&
    typeof (value as { toDate: () => Date }).toDate === "function"
  ) {
    return formatDate((value as { toDate: () => Date }).toDate());
  }
  return "";
}

function toMillis(value: unknown): number | undefined {
  if (!value) return undefined;
  if (value instanceof Date) return value.getTime();
  if (
    value &&
    typeof value === "object" &&
    "toMillis" in value &&
    typeof (value as { toMillis: () => number }).toMillis === "function"
  ) {
    return (value as { toMillis: () => number }).toMillis();
  }
  return undefined;
}

function normalizeDevLogs(logs: unknown): DevLog[] {
  if (!Array.isArray(logs)) return [];
  return logs.map((log: Record<string, unknown>, i: number) => ({
    id: (log.id as string) || String(i),
    title: String(log.title || ""),
    date: normalizeDate(log.date),
    content: String(log.content || ""),
  }));
}

export async function getGames(): Promise<Game[]> {
  await ensureAnonymousLogin();
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const res = await collection
    .orderBy("createdAt", "desc")
    .limit(100)
    .get();
  return (res.data as Game[]).map((item) => ({
    id: item._id,
    slug: item.slug ?? "",
    title: item.title ?? "",
    genre: item.genre ?? "",
    summary: item.summary ?? "",
    description: item.description ?? "",
    cover: item.cover ?? "",
    demoUrl: item.demoUrl ?? "",
    tags: Array.isArray(item.tags) ? item.tags : [],
    devLogs: normalizeDevLogs(item.devLogs),
    featured: item.featured === true,
    createdAt: toMillis(item.createdAt),
    updatedAt: toMillis(item.updatedAt),
  }));
}

export async function getGameBySlug(slug: string): Promise<Game | null> {
  await ensureAnonymousLogin();
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const res = await collection
    .orderBy("createdAt", "desc")
    .limit(200)
    .get();
  const found = (res.data as Game[]).find((item) => item.slug === slug);
  if (!found) return null;
  return {
    id: found._id,
    slug: found.slug ?? "",
    title: found.title ?? "",
    genre: found.genre ?? "",
    summary: found.summary ?? "",
    description: found.description ?? "",
    cover: found.cover ?? "",
    demoUrl: found.demoUrl ?? "",
    tags: Array.isArray(found.tags) ? found.tags : [],
    devLogs: normalizeDevLogs(found.devLogs),
    featured: found.featured === true,
    createdAt: toMillis(found.createdAt),
    updatedAt: toMillis(found.updatedAt),
  };
}

export async function createGame(game: Omit<Game, "id">): Promise<string> {
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const now = new Date();
  const res = await collection.add({
    ...game,
    devLogs: game.devLogs || [],
    tags: game.tags || [],
    featured: game.featured === true,
    createdAt: now,
    updatedAt: now,
  } as unknown as Record<string, unknown>);
  return (res as { id: string }).id;
}

export async function updateGame(id: string, game: Partial<Game>): Promise<void> {
  const db = getDb();
  const collection = db.collection(COLLECTION);
  const doc = collection.doc(id);
  const updateData: Record<string, unknown> = { ...game, updatedAt: new Date() };
  delete updateData.id;
  delete updateData._id;
  await doc.update(updateData);
}

export async function deleteGame(id: string): Promise<void> {
  const db = getDb();
  const collection = db.collection(COLLECTION);
  await collection.doc(id).remove();
}
