import cloudbase from "@cloudbase/js-sdk";

// CloudBase 环境配置
const ENV_ID = "easygame-d0gsh89fna5f3eed2";

let appInstance: ReturnType<typeof cloudbase.init> | null = null;

/**
 * 初始化 CloudBase 应用
 * 同一页面只会初始化一次
 */
export function getApp() {
  if (!appInstance) {
    appInstance = cloudbase.init({
      env: ENV_ID,
    });
  }
  return appInstance;
}

/**
 * 获取数据库实例
 */
export function getDb() {
  return getApp().database();
}

/**
 * 获取当前登录用户（匿名）
 */
export async function ensureAnonymousLogin(): Promise<{
  uid: string;
  isAnonymous: boolean;
} | null> {
  try {
    const app = getApp();
    const auth = app.auth();
    let loginState = await auth.getLoginState();

    if (!loginState || !loginState.user) {
      await auth.signInAnonymously();
      loginState = await auth.getLoginState();
    }

    if (loginState && loginState.user) {
      return {
        uid: loginState.user.uid,
        isAnonymous: true,
      };
    }
    return null;
  } catch (err) {
    console.error("匿名登录失败：", err);
    return null;
  }
}

/**
 * 管理员邮箱密码登录
 */
export async function adminLogin(email: string, password: string) {
  const app = getApp();
  const auth = app.auth();
  await auth.signOut();
  const result = await auth.signInWithEmailAndPassword(email, password);
  return result;
}

/**
 * 管理员注册（首次使用）
 */
export async function adminRegister(email: string, password: string) {
  const app = getApp();
  const auth = app.auth();
  const result = await auth.signUpWithEmailAndPassword(email, password);
  return result;
}

/**
 * 退出登录
 */
export async function logout() {
  const app = getApp();
  await app.auth().signOut();
}

/**
 * 获取当前登录用户信息
 */
export async function getCurrentUser() {
  const app = getApp();
  const loginState = await app.auth().getLoginState();
  return loginState?.user || null;
}
