import { useEffect, useState } from "react";
import { getDb, ensureAnonymousLogin } from "@/lib/cloudbase";

export type ContentType = "posts" | "games";

/**
 * 使用 CloudBase 数据库实现阅读量统计
 */
export function useViewCount(contentType: ContentType, contentId: string) {
  const [views, setViews] = useState<number>(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!contentId) return;
    let cancelled = false;

    async function load() {
      try {
        await ensureAnonymousLogin();
        const db = getDb();
        const res = await db.collection("views")
          .limit(500)
          .get();
        if (cancelled) return;
        if (res.data && res.data.length > 0) {
          const found = res.data.find(
            (item) =>
              (item as { type: string; contentId: string }).type === contentType &&
              (item as { type: string; contentId: string }).contentId === contentId
          );
          setViews(found ? Number((found as { count: number }).count) || 0 : 0);
        } else {
          setViews(0);
        }
        setLoading(false);
      } catch {
        if (!cancelled) setLoading(false);
      }
    }

    load();

    // 自增阅读量
    const storageKey = `viewed_${contentType}_${contentId}`;
    if (!sessionStorage.getItem(storageKey)) {
      sessionStorage.setItem(storageKey, "true");
      (async () => {
        try {
          await ensureAnonymousLogin();
          const db = getDb();
          const collection = db.collection("views");
          const res = await collection.limit(500).get();
          const found = res.data?.find(
            (item) =>
              (item as { type: string; contentId: string }).type === contentType &&
              (item as { type: string; contentId: string }).contentId === contentId
          );
          if (found) {
            const doc = found as { _id: string; count: number };
            await collection.doc(doc._id).update({ count: (Number(doc.count) || 0) + 1 });
          } else {
            await collection.add({ type: contentType, contentId, count: 1 });
          }
        } catch {
          // 自增失败不报错
        }
      })();
    }

    return () => {
      cancelled = true;
    };
  }, [contentType, contentId]);

  return { views, loading };
}
