import { useEffect, useState, useCallback } from "react";
import { getDb, ensureAnonymousLogin } from "@/lib/cloudbase";

export type ContentType = "posts" | "games";

/**
 * 使用 CloudBase 数据库实现点赞
 * 数据结构：likes 集合下，按 { type, contentId } 作为业务键
 */
export function useLikes(contentType: ContentType, contentId: string) {
  const [likes, setLikes] = useState<number>(0);
  const [liked, setLiked] = useState<boolean>(false);
  const [loading, setLoading] = useState(true);

  const storageKey = `liked_${contentType}_${contentId}`;

  useEffect(() => {
    setLiked(localStorage.getItem(storageKey) === "true");
  }, [storageKey]);

  useEffect(() => {
    if (!contentId) return;
    let cancelled = false;

    async function load() {
      try {
        await ensureAnonymousLogin();
        const db = getDb();
        const res = await db.collection("likes")
          .limit(500)
          .get();
        if (cancelled) return;
        if (res.data && res.data.length > 0) {
          const found = res.data.find(
            (item) =>
              (item as { type: string; contentId: string }).type === contentType &&
              (item as { type: string; contentId: string }).contentId === contentId
          );
          setLikes(found ? Number((found as { count: number }).count) || 0 : 0);
        } else {
          setLikes(0);
        }
        setLoading(false);
      } catch {
        if (!cancelled) setLoading(false);
      }
    }

    load();
    const timer = setInterval(load, 30000);
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [contentType, contentId]);

  const toggleLike = useCallback(async () => {
    if (!contentId) return;

    const newLiked = !liked;
    const db = getDb();
    const collection = db.collection("likes");

    try {
      await ensureAnonymousLogin();
      const res = await collection.limit(500).get();
      const found = res.data?.find(
        (item) =>
          (item as { type: string; contentId: string }).type === contentType &&
          (item as { type: string; contentId: string }).contentId === contentId
      );

      if (found) {
        const doc = found as { _id: string; count: number };
        const currentCount = Number(doc.count) || 0;
        const newCount = newLiked ? currentCount + 1 : Math.max(0, currentCount - 1);
        await collection.doc(doc._id).update({ count: newCount });
        setLikes(newCount);
      } else {
        await collection.add({ type: contentType, contentId, count: 1 });
        setLikes(1);
      }

      setLiked(newLiked);
      localStorage.setItem(storageKey, newLiked ? "true" : "false");
    } catch {
      // 写入失败时不切换状态
    }
  }, [contentType, contentId, liked, storageKey]);

  return { likes, liked, loading, toggleLike };
}
